mapper.select:
SELECT id, content, embedding, metadata::text AS metadata, user_id,
       parent_id, chunk_type, title, created_at
FROM ai_knowledge_chunk
WHERE embedding IS NOT NULL
  AND chunk_type = 'CHILD'
  AND (1 - (embedding <=> #{queryVector, typeHandler=com.example.langchain4j.repository.typehandler.VectorTypeHandler})) >= #{minScore}
  AND (user_id = #{userId} OR (NOT #{privateOnly} AND user_id IS NULL))
ORDER BY embedding <=> #{queryVector, typeHandler=com.example.langchain4j.repository.typehandler.VectorTypeHandler}
LIMIT #{topK}

mapper.delete:
DELETE FROM ai_knowledge_chunk
WHERE id = #{id}
  AND user_id = #{userId}
